import React,{useState,useMemo} from 'react';
import {Activity,Store,Wallet,TrendingUp,Users,ShoppingBag,Clock,ShieldCheck,Plus,Download,ArrowRight,Eye,Pause,Play,Check,X,Search,MapPin,Send,ExternalLink,FileText,AlertTriangle,Truck,Settings2,Image,CheckCircle2,LogOut,RefreshCw} from 'lucide-react';
import {today,shift,money,daysBetween} from './model.mjs';
import {PERMISSIONS,ROLES,filterRows,businessDate,orderRows,saas,saasStatus,ageAt,sessionState,ruleStep,newId} from './operations.mjs';
const orderLabels={new:'Novo',reviewing:'Em conferência',confirmed:'Confirmado',ready:'Pronto',awaiting_approval:'Aguarda cliente',revision_approved:'Revisão aprovada',rejected:'Recusado',preparing:'Em preparo',out_for_delivery:'Saiu entrega',completed:'Entregue',cancelled:'Cancelado'};
export function GlobalFilters({filters:f,setFilters,setToast,data}){function change(key,value){const next={...f,[key]:value};if(!next.start||!next.end)return;if(next.start>next.end||daysBetween(next.start,next.end)>366){setToast('Escolha um intervalo válido de até 367 dias.');return}setFilters(next)}return <section className="ops-filters"><div className="ops-filter-title"><Settings2 size={16}/><strong>Filtros do painel</strong><span>Horário de Brasília</span></div><div className="ops-filter-inputs"><label>De<input type="date" aria-label="Filtro início" value={f.start} onChange={e=>change('start',e.target.value)}/></label><label>Até<input type="date" aria-label="Filtro fim" value={f.end} onChange={e=>change('end',e.target.value)}/></label><label>Das<select aria-label="Filtro hora inicial" value={f.from} onChange={e=>change('from',e.target.value)}><option value="">Todas</option>{Array.from({length:24},(_,i)=><option key={i} value={i}>{String(i).padStart(2,'0')}h</option>)}</select></label><label>Até<select aria-label="Filtro hora final" value={f.to} onChange={e=>change('to',e.target.value)}><option value="">Todas</option>{Array.from({length:24},(_,i)=><option key={i} value={i}>{String(i).padStart(2,'0')}h</option>)}</select></label><label>Cidade<select aria-label="Filtro cidade global" value={f.city} onChange={e=>change('city',e.target.value)}><option value="">Todas</option>{data.settings.cities.map(c=><option key={c}>{c}</option>)}</select></label><label>Loja<select aria-label="Filtro loja global" value={f.store} onChange={e=>change('store',e.target.value)}><option value="">Todas</option>{data.stores.filter(s=>!s.demo).map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select></label><label>Bairro<select aria-label="Filtro bairro global" value={f.neighborhood} onChange={e=>change('neighborhood',e.target.value)}><option value="">Todos</option>{[...new Set(data.stores.map(s=>s.neighborhood).filter(Boolean))].map(n=><option key={n}>{n}</option>)}</select></label><button className="filter-reset" onClick={()=>setFilters({start:shift(today(),-6),end:today(),from:'',to:'',city:'',store:'',neighborhood:'',status:'',q:''})}><RefreshCw size={14}/>Limpar</button></div><div className="ops-filter-foot"><span>{f.from!==''&&f.to!==''&&Number(f.from)>Number(f.to)?'Faixa noturna: as horas após a meia-noite contam no dia anterior.':'Datas inclusivas. Cadastros sem horário usam os filtros próprios do módulo.'}</span><button onClick={()=>setFilters({...f,start:today(),end:today(),from:'18',to:'2'})}>Turno 18h–02h</button></div></section>}
function GridTable({columns,rows,empty='Nenhum registro neste filtro.'}){return <div className="table-scroll"><table><thead><tr>{columns.map(c=><th key={c[0]}>{c[0]}</th>)}</tr></thead><tbody>{rows.map((r,i)=><tr key={r.id||i}>{columns.map(([label,render])=><td key={label}>{typeof render==='function'?render(r):r[render]}</td>)}</tr>)}</tbody></table>{!rows.length&&<div className="ops-empty">{empty}</div>}</div>}
function Matches({children}){return <p className="ops-matches">{children}</p>}
function Export({p,rows,name}){const {Button}=p.ui;return <div className="row-actions"><Button variant="secondary small" icon={Download} onClick={()=>p.exportExcel(rows,name)}>Excel</Button><Button variant="secondary small" icon={FileText} onClick={()=>window.print()}>Imprimir / PDF</Button></div>}
export function Executive(p){const {data:d,filters:f,ui:{Panel,Tile,Badge,Button}}=p;const rows=orderRows(d,f),done=rows.filter(o=>o.status==='completed'),revenue=done.reduce((a,o)=>a+o.total,0),stores=d.stores.filter(s=>!s.demo&&(!f.city||s.city===f.city)&&(!f.store||s.id===Number(f.store))&&(!f.neighborhood||s.neighborhood===f.neighborhood)),fin=saas(d,stores);const [metric,setMetric]=useState('count');const hours=Array.from({length:24},(_,hour)=>({hour,count:done.filter(o=>o.hour===hour).length,total:done.filter(o=>o.hour===hour).reduce((a,o)=>a+o.total,0)}));const chartHours=f.from!==''&&f.to!==''&&Number(f.from)>Number(f.to)?[...hours.slice(Number(f.from)),...hours.slice(0,Number(f.to)+1)]:hours.filter(h=>(f.from===''||h.hour>=Number(f.from))&&(f.to===''||h.hour<=Number(f.to)));const max=Math.max(1,...chartHours.map(h=>h[metric]));const inScope=d.orders.filter(o=>stores.some(s=>s.id===o.store)),now=today(),previous=shift(now,-1);const countDate=date=>inScope.filter(o=>o.date===date).length;const idle=stores.filter(s=>s.approval==='approved'&&!inScope.some(o=>o.store===s.id&&o.status==='completed'&&o.date>=shift(now,-6)));const ranks=stores.map(s=>({...s,sales:done.filter(o=>o.store===s.id).reduce((a,o)=>a+o.total,0),count:done.filter(o=>o.store===s.id).length})).filter(s=>s.count).sort((a,b)=>b.sales-a.sales);
 const products=new Map();for(const o of done)for(const i of o.items){const key=o.store+':'+i.name;const x=products.get(key)||{name:i.name,store:o.storeName,qty:0,total:0};x.qty+=i.qty;x.total+=i.price*i.qty;products.set(key,x)}
 return <><div className="executive-label"><span className="live-led"/>VISÃO EXECUTIVA <span>Dados do banco · valores sem plano SaaS registrado ficam zerados</span><Export p={p} rows={rows.map(o=>({Pedido:o.id,Loja:o.storeName,Data:o.date,Hora:o.hour,Status:orderLabels[o.status]||o.status,'Valor R$':o.total/100}))} name="nowup-executivo"/></div><div className="metrics"><Tile label="MRR · mensalidades" value={money(fin.mrr)} icon={Wallet} note="Carteira atual no recorte de lojas"/><Tile label="ARR · anualizado" value={money(fin.arr)} icon={TrendingUp} note="MRR atual × 12"/><Tile label="Churn mensal" value={(fin.churn*100).toFixed(1)+'%'} icon={Activity} note={`${fin.lost} cancelada(s) ÷ ${fin.initial} ativas no início`}/><Tile label="LTV estimado" value={fin.ltv===null?'Sem base':money(fin.ltv)} icon={Users} note="ARPU ÷ churn; estimativa ilustrativa"/></div><div className="ops-kpis"><div><strong>{stores.filter(s=>s.approval==='approved'&&!s.paused&&!s.blocked&&!s.cancelledAt).length}</strong><span>Lojas ativas</span></div><div><strong>{stores.filter(s=>s.paused||s.blocked||s.cancelledAt||s.approval!=='approved').length}</strong><span>Inativas / pendentes</span></div><div><strong>{stores.filter(s=>saasStatus(s)==='Teste Grátis').length}</strong><span>Em teste</span></div><div><strong>{countDate(now)}</strong><span>Pedidos hoje*</span></div><div><strong>{countDate(previous)}</strong><span>Pedidos ontem*</span></div><div><strong>{(inScope.filter(o=>o.date>=shift(now,-6)&&o.date<=now).length/7).toFixed(1)}</strong><span>Média 7 dias*</span></div></div><Matches>*Hoje, ontem, média de 7 dias e carteira SaaS usam referências fixas indicadas. Os filtros de período e horário afetam as vendas, gráficos, ranking e exportação abaixo.</Matches><div className="metrics compact-metrics"><Tile label="Vendas no período" value={money(revenue)} icon={ShoppingBag} note="Pedidos entregues; não é receita NowUp"/><Tile label="Ticket médio" value={money(done.length?revenue/done.length:0)} icon={Wallet} note="Vendas ÷ entregues"/><Tile label="Pedidos no filtro" value={rows.length} icon={Activity} note={`${done.length} entregues`}/><Tile label="Cancelamentos" value={rows.filter(o=>o.status==='cancelled').length} icon={X} note="Pedidos cancelados no recorte"/></div><div className="dashboard-grid"><Panel title="Vendas por hora" subtitle="Escolha faixa horária e período nos filtros acima." action={<select className="small-select" aria-label="Métrica das vendas" value={metric} onChange={e=>setMetric(e.target.value)}><option value="count">Pedidos</option><option value="total">Valor vendido</option></select>}><div className="ops-chart">{chartHours.map(h=><div key={h.hour}><b title={`${h.hour}h · ${h.count} pedidos · ${money(h.total)}`} style={{height:Math.max(2,h[metric]/max*160)}}/><span>{h.hour}h</span></div>)}</div><GridTable columns={[["Hora",x=>x.hour+'h'],['Pedidos','count'],['Vendas',x=>money(x.total)]]} rows={chartHours.filter(x=>x.count)}/></Panel><Panel title="Alertas operacionais" subtitle="Os alertas usam a carteira atual da cidade e loja filtradas."><button type="button" className="ops-alert" onClick={()=>p.navigate('stores')}><AlertTriangle/><div><strong>{idle.length} lojas sem vender há 7 dias</strong><p>Revisar catálogo, disponibilidade e operação</p></div><ArrowRight size={17}/></button><button type="button" className="ops-alert" onClick={()=>p.navigate('finance')}><Wallet/><div><strong>{money(fin.overdue)} em mensalidades vencidas</strong><p>Revisar a régua de cobrança</p></div><ArrowRight size={17}/></button><button type="button" className="ops-alert" onClick={()=>p.navigate('support')}><ShieldCheck/><div><strong>{d.tickets.filter(t=>t.status!=='Resolvido'&&stores.some(s=>s.id===t.store)).length} chamados abertos</strong><p>Atendimento e denúncias</p></div><ArrowRight size={17}/></button></Panel></div><Panel title="Mapa de calor de pedidos" subtitle="Todos os pedidos no filtro · dia da semana × hora · horário de Brasília"><div className="heatmap"><div className="heatmap-header"><span/>{Array.from({length:24},(_,i)=><small key={i}>{i%3===0?i+'h':''}</small>)}</div>{['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'].map((name,n)=><div className="heatmap-row" key={name}><span>{name}</span>{Array.from({length:24},(_,hour)=>{const count=rows.filter(o=>new Date(businessDate(o,f)+'T12:00:00Z').getUTCDay()===n&&o.hour===hour).length;return <i key={hour} title={`${name} ${hour}h: ${count} pedido(s)`} aria-label={`${name} ${hour}h: ${count} pedido(s)`} style={{background:count?'rgba(154,104,255,'+Math.min(1,.2+count*.1)+')':'#222635'}}/>})}</div>)}</div><Matches>Mais escuro: menos pedidos. Mais roxo: maior volume.</Matches></Panel><div className="two-columns"><Panel title="Ranking de lojas" subtitle="Vendas e pedidos entregues no filtro"><GridTable columns={[["Loja","name"],['Pedidos','count'],['Vendas',s=>money(s.sales)]]} rows={ranks}/></Panel><Panel title="Produtos mais vendidos" subtitle="Quantidades em pedidos entregues"><GridTable columns={[["Produto","name"],['Loja','store'],['Qtd.','qty'],['Itens',i=>money(i.total)]]} rows={[...products.values()].sort((a,b)=>b.qty-a.qty)}/></Panel></div></>}
export function Kanban(p){const {data:d,commit,form,confirm,setModal,filters:f,ui:{Panel,Button,Badge,Field,FileField}}=p;const [query,setQuery]=useState('');const stages=['Leads','Docs Enviados','Em Análise','Aprovados','Reprovados'];const stores=d.stores.filter(s=>!s.demo&&(!f.city||s.city===f.city)&&(!f.store||s.id===Number(f.store))&&(!f.neighborhood||s.neighborhood===f.neighborhood)&&s.name.toLowerCase().includes(query.toLowerCase()));
 function stage(s,value){if(value==='Reprovados'){form('Reprovar loja',<Field label="Motivo da reprovação" name="reason" type="textarea" required/>,v=>commit(x=>Object.assign(x.stores.find(a=>a.id===s.id),{stage:value,approval:'rejected',rejection:v.reason}),'Reprovação: '+s.name+' · '+v.reason));return}confirm('Mover loja para '+value+'?',`A alteração de ${s.name} será registrada no servidor.`,()=>commit(x=>Object.assign(x.stores.find(a=>a.id===s.id),{stage:value,approval:value==='Aprovados'?'approved':'pending'}),'Etapa KYC alterada: '+s.name+' → '+value))}
 function edit(s){form('Cadastro · '+s.name,<><div className="form-grid"><Field label="Loja" name="name" value={s.name} required/><Field label="Responsável" name="owner" value={s.owner} required/><Field label="WhatsApp com DDD" name="phone" value={s.phone}/><Field label="CNPJ (fictício)" name="document" value={s.document}/><Field label="Cidade" name="city" value={s.city} required/><Field label="Bairro" name="neighborhood" value={s.neighborhood}/><Field label="Raio de entrega (km)" name="radius" type="number" value={s.radius} min="0" max="100"/><Field label="Preparo (min)" name="prep" type="number" value={s.prep} min="1" max="240"/></div><Field label="Endereço" name="address" value={s.address}/><h3>Funcionamento por dia</h3><div className="form-grid">{['Segunda','Terça','Quarta','Quinta','Sexta','Sábado','Domingo'].map((n,i)=><Field key={n} label={n} name={'day'+i} value={s.hoursByDay?.[i]||''} placeholder="18:00–02:00 ou fechado"/>)}</div></>,v=>commit(x=>{const t=x.stores.find(a=>a.id===s.id);Object.assign(t,{...v,radius:Number(v.radius),prep:Number(v.prep),hoursByDay:Array.from({length:7},(_,i)=>v['day'+i])})},'Cadastro administrativo editado: '+s.name),{wide:true})}
 function kyc(s){form('Documentos KYC · '+s.name,<><div className="alert">Use apenas arquivos fictícios. A prévia registra o nome do arquivo e a revisão, sem armazenar RG, selfie ou documentos reais.</div>{['RG','CNPJ','Alvará','Foto Fachada','Selfie Dono'].map((n,i)=><div className="kyc-row" key={n}><Field label={n+' · situação'} name={'state'+i} options={['Pendente','Recebido','Aprovado','Reprovado']} value={s.kyc?.[n]||'Pendente'}/><label className="field"><span>Anexo demonstrativo</span><input name={'doc'+i} type="file" accept=".png,.jpg,.jpeg,.webp,.pdf"/>{s.documents?.[n]&&<small>Nome registrado: {s.documents[n]}</small>}</label></div>)}</>,v=>commit(x=>{const t=x.stores.find(a=>a.id===s.id);for(const [i,n] of ['RG','CNPJ','Alvará','Foto Fachada','Selfie Dono'].entries()){t.kyc[n]=v['state'+i];if(v['doc'+i]?.name)t.documents[n]=v['doc'+i].name}},'Revisão documental simulada: '+s.name),{wide:true})}
 function message(s){form('Mensagem oficial para '+s.name,<><Field label="Mensagem" name="message" type="textarea" maxLength={1000} required/><p className="muted">Cria uma conversa demonstrativa de suporte. Não envia WhatsApp.</p></>,v=>commit(x=>x.tickets.unshift({id:newId(),store:s.id,customer:null,reason:'Mensagem administrativa',status:'Aberto',date:today(),hour:Number(new Intl.DateTimeFormat('en',{timeZone:'America/Sao_Paulo',hour:'numeric',hourCycle:'h23'}).format(new Date())),city:s.city,messages:[{actor:'Super ADM',body:v.message,date:new Date().toISOString()}]}),'Mensagem administrativa registrada: '+s.name))}
 function impersonate(s){p.setToast('Acesso assistido ainda não ativado. Use a visualização pública da loja.')}
 function details(s){const orders=d.orders.filter(o=>o.store===s.id);setModal({title:s.name,wide:true,body:<div className="modal-content"><div className="metrics"><div><strong>{orders.length}</strong><p>Pedidos cadastrados</p></div><div><strong>{s.rating.toFixed(1)}</strong><p>Avaliação cadastrada</p></div><div><strong>{orders.filter(o=>o.status==='cancelled').length}</strong><p>Cancelados</p></div></div><div className="row-actions"><Button onClick={()=>edit(s)}>Editar cadastro</Button><Button variant="secondary" onClick={()=>kyc(s)}>Documentos KYC</Button><Button variant="secondary" onClick={()=>impersonate(s)}>Acesso assistido · não conectado</Button><Button variant="secondary" onClick={()=>message(s)}>Mensagem oficial</Button><Button variant="secondary" onClick={()=>form('Alterar plano · '+s.name,<Field label="Plano" name="plan" value={s.plan} options={d.plans.map(x=>[x.id,x.name+' · '+money(x.price)])}/>,v=>commit(x=>{const t=x.stores.find(a=>a.id===s.id);t.plan=v.plan;t.price=x.plans.find(a=>a.id===v.plan).price},'Plano alterado: '+s.name))}>Upgrade de plano</Button></div><div className="row-actions"><Button variant="secondary" onClick={()=>confirm('Pausar ou reativar loja?',s.name,()=>commit(x=>{const t=x.stores.find(a=>a.id===s.id);t.paused=!t.paused},'Disponibilidade alterada: '+s.name))}>{s.paused?'Reativar':'Pausar'}</Button><Button variant="secondary" onClick={()=>form('Bloquear loja',<Field label="Justificativa obrigatória" name="reason" type="textarea" required/>,v=>commit(x=>Object.assign(x.stores.find(a=>a.id===s.id),{blocked:true,blockReason:v.reason}),'Loja bloqueada: '+s.name+' · '+v.reason))}>Bloquear</Button><Button variant="secondary" onClick={()=>commit(x=>Object.assign(x.stores.find(a=>a.id===s.id),{blocked:false,blockReason:''}),'Bloqueio administrativo removido: '+s.name)}>Desbloquear</Button>{s.phone?<a className="btn secondary" href={'https://wa.me/'+(s.phone.replace(/\D/g,'').startsWith('55')?'':'55')+s.phone.replace(/\D/g,'')} target="_blank" rel="noreferrer">Abrir WhatsApp</a>:<span className="muted">Cadastre WhatsApp para abrir a conversa.</span>}</div><div className="alert">Intervenções demonstrativas ficam no log. Editar botões e funcionalidades por plano é feito no controle abaixo.</div><Button variant="secondary" onClick={()=>form('Recursos e botões · '+s.name,<div className="permission-grid">{['Pedidos internos','WhatsApp','Cardápio','Promoções'].map(n=><label key={n}><input type="checkbox" name={n} defaultChecked={s.resources?.includes(n)}/>{n}</label>)}</div>,v=>commit(x=>x.stores.find(a=>a.id===s.id).resources=Object.keys(v),'Recursos administrativos alterados: '+s.name))}>Configurar botões da loja</Button></div>})}
 return <><div className="section-toolbar"><div className="searchbox"><Search size={16}/><input placeholder="Buscar lojista no Kanban" value={query} onChange={e=>setQuery(e.target.value)}/></div><Button icon={Plus} onClick={()=>form('Adicionar lead',<><Field label="Nome da loja" name="name" required/><Field label="Responsável" name="owner" required/><Field label="Cidade" name="city" value="Ubatuba" required/></>,v=>commit(x=>x.stores.push({...structuredClone(x.stores.find(a=>a.id===201)),...v,id:newId(),stage:'Leads',approval:'pending',kyc:{},documents:{},price:0,due:'',paused:false,blocked:false}),'Lead criado: '+v.name))}>Novo lead</Button></div><Matches>{stores.length} lojas no recorte cadastral. Data e hora são aplicadas aos eventos nos relatórios, não à situação atual do Kanban.</Matches><div className="kanban">{stages.map(col=><section key={col}><header><span className={'stage-dot stage-'+stages.indexOf(col)}/><h2>{col}</h2><b>{stores.filter(s=>s.stage===col).length}</b></header>{stores.filter(s=>s.stage===col).map(s=><article key={s.id} className="kanban-card"><div className="kanban-store-icon"><Store size={21}/><Badge tone={s.blocked?'red':s.paused?'amber':'purple'}>{s.blocked?'Bloqueada':s.paused?'Pausada':d.plans.find(a=>a.id===s.plan)?.name}</Badge></div><h3>{s.name}</h3><p>{s.owner}</p><small><MapPin size={12}/>{s.city} · {s.neighborhood}</small><div className="kanban-performance"><span>{d.orders.filter(o=>o.store===s.id).length} pedidos</span><span>★ {s.rating.toFixed(1)}</span></div><select aria-label={'Etapa '+s.name} value={s.stage} onChange={e=>stage(s,e.target.value)}>{stages.map(n=><option key={n}>{n}</option>)}</select><Button variant="secondary small" onClick={()=>details(s)}>Abrir cadastro <ArrowRight size={13}/></Button></article>)}</section>)}</div></>}
export function FinanceOps(p){const {data:d,filters:f,ui:{Panel,Tile,Button,Badge,Field},commit,form,confirm}=p;const [status,setStatus]=useState(''),[tab,setTab]=useState('subscriptions');const stores=d.stores.filter(s=>!s.demo&&(!f.city||s.city===f.city)&&(!f.store||s.id===Number(f.store))&&(!f.neighborhood||s.neighborhood===f.neighborhood));const stats=saas(d,stores);const rows=stores.filter(s=>!status||saasStatus(s)===status);const receipts=d.payments.filter(x=>stores.some(s=>s.id===x.store)&&x.date>=f.start&&x.date<=f.end);
 function change(s){form('Contrato · '+s.name,<><Field label="Plano" name="plan" options={d.plans.map(a=>[a.id,a.name+' · '+money(a.price)])} value={s.plan}/><Field label="Próximo vencimento" name="due" type="date" value={s.due||shift(today(),7)} required/><Field label="Teste grátis até · 7 dias sugeridos" name="trialUntil" type="date" value={s.trialUntil||''}/><Field label="Forma de pagamento" name="method" options={['Pix','Cartão']} value={s.method}/><Field label="Cupom de mensalidade" name="billingCoupon" value={s.billingCoupon||''} options={[["","Sem cupom"],...d.billingCoupons.map(c=>[c.code,c.code])]}/><p className="muted">Pix recorrente e cartão precisam de gateway, consentimento e webhook confirmado. A criação da assinatura ocorre pela ação Preparar cobrança Asaas, na área de documentos.</p></>,v=>commit(x=>{const t=x.stores.find(a=>a.id===s.id);Object.assign(t,v,{price:x.plans.find(a=>a.id===v.plan).price})},'Contrato SaaS alterado: '+s.name))}
 function paid(s){form('Registrar anotação administrativa de pagamento',<><Field label="Valor (R$)" name="amount" type="number" min="0.01" step="0.01" value={s.price/100} required/><Field label="Data do pagamento" name="date" type="date" value={today()} required/><Field label="Próximo vencimento" name="due" type="date" value={shift(today(),30)} required/><Field label="Referência" name="reference" required/></>,v=>{if(v.due<=v.date)throw Error('O próximo vencimento deve ser posterior ao pagamento.');commit(x=>{x.payments.unshift({id:newId(),store:s.id,amount:Math.round(Number(v.amount)*100),date:v.date,method:s.method,reference:v.reference});Object.assign(x.stores.find(a=>a.id===s.id),{due:v.due,trialUntil:''})},'Anotação administrativa registrada (não confirma Asaas): '+s.name)})}
 return <><div className="metrics"><Tile label="MRR atual" value={money(stats.mrr)} icon={Wallet} note="Não inclui teste, canceladas e leads"/><Tile label="A receber em 30 dias" value={money(stats.receivable)} icon={Clock} note="Vencimentos futuros no recorte atual"/><Tile label="Inadimplência" value={money(stats.overdue)} icon={AlertTriangle} note="Mensalidades vencidas"/><Tile label="Churn do mês" value={(stats.churn*100).toFixed(1)+'%'} icon={Activity} note={`${stats.lost} cancelada(s) na base de ${stats.initial}`}/></div><Matches>Carteira atual: os filtros de cidade, bairro e loja afetam estes indicadores. O filtro de datas afeta o histórico de pagamentos; horários não se aplicam a vencimentos.</Matches><div className="section-toolbar"><div className="section-tabs">{[['subscriptions','Assinaturas'],['payments','Pagamentos'],['churn','Churn'],['coupons','Cupons mensalidade']].map(([k,t])=><button key={k} className={tab===k?'selected':''} onClick={()=>setTab(k)}>{t}</button>)}</div><Export p={p} rows={(tab==='payments'?receipts.map(x=>({Loja:d.stores.find(s=>s.id===x.store)?.name,Data:x.date,Valor:x.amount/100,Forma:x.method})):rows.map(s=>({Loja:s.name,Plano:s.plan,Mensalidade:s.price/100,Vencimento:s.due,Status:saasStatus(s)})))} name="nowup-saas"/></div>
 {tab==='subscriptions'&&<><div className="plan-summary">{d.plans.map(plan=><div key={plan.id}><span>{plan.name}</span><strong>{money(plan.price)}<small>/mês</small></strong><button onClick={()=>form('Editar preço '+plan.name,<Field label="Mensalidade (R$)" name="price" type="number" min="1" step="0.01" value={plan.price/100} required/>,v=>commit(x=>x.plans.find(a=>a.id===plan.id).price=Math.round(Number(v.price)*100),'Preço do plano alterado; contratos anteriores preservados'))}>Editar preço</button></div>)}</div><Panel title="Assinaturas e régua de cobrança" subtitle="D-3 lembrete · D0 cobrança · D+1 bloqueio simulado · D+3 revisão" action={<select className="small-select" value={status} aria-label="Situação da assinatura" onChange={e=>setStatus(e.target.value)}><option value="">Todas as situações</option>{['Ativa','Teste Grátis','Vencendo 3 dias','Vencida','Cancelada','Sem contrato'].map(a=><option key={a}>{a}</option>)}</select>}><GridTable rows={rows} columns={[["Loja",s=><><strong>{s.name}</strong><small>{s.city}</small></>],['Mensalidade',s=>money(s.price)],['Status',s=><Badge tone={saasStatus(s)==='Vencida'?'red':'purple'}>{saasStatus(s)}</Badge>],['Vencimento',s=>s.due||'Não informado'],['Régua',s=><><span>{ruleStep(s)}</span>{d.settings.autoBlock&&saasStatus(s)==='Vencida'&&<small className="text-red">Bloqueada na simulação</small>}</>],['Ações',s=><div className="row-actions nowrap"><Button variant="secondary small" onClick={()=>change(s)}>Contrato</Button><button className="icon-btn" title="Registrar pagamento" aria-label={'Pagamento '+s.name} onClick={()=>paid(s)}><Wallet size={16}/></button><button className="icon-btn" title="Cancelar assinatura" aria-label={'Cancelar '+s.name} onClick={()=>confirm('Cancelar assinatura?',s.name,()=>commit(x=>x.stores.find(a=>a.id===s.id).cancelledAt=today(),'Assinatura cancelada: '+s.name))}><X size={16}/></button><button className="icon-btn" aria-label={'Simular cobrança '+s.name} title="Preparar cobrança" onClick={()=>form('Preparar mensagem de cobrança',<><Field label="Mensagem" name="message" type="textarea" value={`Olá! A mensalidade NowUp de ${s.name} é ${money(s.price)}. Vencimento: ${s.due}.`} required/><p className="muted">A mensagem será registrada no log; não enviada.</p></>,v=>commit(()=>{},'Cobrança preparada, não enviada: '+s.name+' · '+v.message))}><Send size={16}/></button></div>]]}/></Panel><div className="rule-card"><ShieldCheck/><div><strong>Bloqueio em D+4 após o vencimento</strong><p>D+1 a D+3 têm carência. O worker bloqueia em D+4; confirmação de pagamento reativa somente o bloqueio financeiro.</p></div><label className="switch"><input type="checkbox" aria-label="Bloqueio automático em D+4" checked={d.settings.autoBlock} onChange={e=>commit(x=>x.settings.autoBlock=e.target.checked,'Bloqueio automático em D+4 alterado')}/><span/></label></div></>}
 {tab==='payments'&&<Panel title="Histórico de pagamentos" subtitle="Filtrado por datas e pelas lojas selecionadas"><GridTable columns={[["Loja",x=>d.stores.find(s=>s.id===x.store)?.name],['Data','date'],['Valor',x=>money(x.amount)],['Forma','method'],['Referência','reference']]} rows={receipts}/></Panel>}
 {tab==='churn'&&<Panel title="Cancelamentos da carteira" subtitle="Canceladas no período escolhido"><GridTable columns={[["Loja","name"],['Plano','plan'],['Cancelamento','cancelledAt'],['Mensalidade perdida',s=>money(s.price)]]} rows={stores.filter(s=>s.cancelledAt>=f.start&&s.cancelledAt<=f.end)}/></Panel>}
 {tab==='coupons'&&<Panel title="Cupons para mensalidades" subtitle="Separados dos cupons de compra; aplicação no gateway pendente." action={<Button icon={Plus} onClick={()=>form('Cupom de mensalidade',<><Field label="Código" name="code" required pattern="[A-Za-z0-9_-]{3,24}"/><Field label="Desconto (%)" name="percent" type="number" min="1" max="100" required/><Field label="Duração (meses)" name="months" type="number" min="1" max="12" value="1" required/></>,v=>{if(d.billingCoupons.some(c=>c.code===v.code.toUpperCase()))throw Error('Código já cadastrado.');commit(x=>x.billingCoupons.push({...v,id:newId(),code:v.code.toUpperCase()}),'Cupom de mensalidade criado')})}>Novo cupom</Button>}><GridTable rows={d.billingCoupons} columns={[["Código","code"],['Desconto',c=>c.percent+'%'],['Duração',c=>c.months+' mês(es)']]}/></Panel>}</>}
export function LiveOrders(p){const {data:d,filters:f,clock,commit,form,ui:{Panel,Button,Badge,Field}}=p;const [status,setStatus]=useState(''),[live,setLive]=useState(true);const rows=orderRows(d,f).filter(o=>(!status||o.status===status)&&(!live||o.live));const late=o=>o.live&&['preparing','out_for_delivery'].includes(o.status)&&clock-new Date(o.createdAt)>50*60000;
 return <><div className="section-toolbar"><span className="live-pill"><i/>Torre de controle · dados do servidor</span><div className="row-actions"><label className="checkbox-inline"><input type="checkbox" checked={live} onChange={e=>setLive(e.target.checked)}/>Somente pedidos em acompanhamento</label><select className="small-select" value={status} aria-label="Status pedido" onChange={e=>setStatus(e.target.value)}><option value="">Todos os status</option>{Object.entries(orderLabels).map(([v,n])=><option key={v} value={v}>{n}</option>)}</select></div></div><Matches>Relógio atualizado a cada 30 segundos. Dados reais carregados do servidor; use Atualizar para consultar alterações recentes. {rows.length} pedido(s) no filtro.</Matches><Panel title="Pedidos de todas as lojas" subtitle="Alertas vermelhos após 50 minutos em preparo ou entrega." action={<Export p={p} rows={rows.map(o=>({Pedido:o.id,Loja:o.storeName,Cliente:o.customerName,Status:orderLabels[o.status],Valor:o.total/100}))} name="nowup-pedidos"/>}><div className="live-orders">{rows.map(o=><article key={o.id} className={'live-order '+(late(o)?'late':'')}><header><strong>#{o.id}</strong><Badge tone={late(o)?'red':o.status==='completed'?'green':'purple'}>{orderLabels[o.status]||o.status}</Badge></header><h3>{o.storeName}</h3><p>{o.customerName} · {o.city}</p><div className="order-value"><strong>{money(o.total)}</strong><span><Clock size={13}/>{o.createdAt?Math.max(0,Math.floor((clock-new Date(o.createdAt))/60000))+' min':o.hour+'h'}</span></div>{late(o)&&<div className="late-warning"><AlertTriangle size={14}/>Mais de 50 minutos · verificar</div>}<small>Entrega: {d.couriers.find(c=>c.id===o.courier)?.name||'Não atribuído'}</small><Button variant="secondary small" onClick={()=>form('Atualizar pedido #'+o.id,<><Field label="Status" name="status" options={Object.entries(orderLabels)} value={o.status}/><Field label="Motoboy" name="courier" options={[["","Sem atribuição"],...d.couriers.map(c=>[c.id,c.name])]} value={o.courier}/><Field label="Motivo / observação" name="reason" type="textarea" required/></>,v=>commit(x=>Object.assign(x.orders.find(a=>a.id===o.id),{status:v.status,courier:Number(v.courier)||null}),'Pedido #'+o.id+' atualizado · '+v.reason))}>Ver / atualizar</Button></article>)}</div>{!rows.length&&<div className="ops-empty">Nenhum pedido. Amplie o período ou desmarque o acompanhamento.</div>}</Panel></>}
export function Customers(p){const {data:d,filters:f,form,commit,confirm,ui:{Panel,Button,Badge,Field}}=p;const [q,setQ]=useState(''),[only,setOnly]=useState('');const orders=orderRows(d,{...f,store:f.store});const rows=d.customers.filter(c=>(!f.city||c.city===f.city)&&(!f.neighborhood||c.neighborhood===f.neighborhood)&&(!f.store||orders.some(o=>o.customer===c.id))&&(!q||c.name.toLowerCase().includes(q.toLowerCase()))&&(!only||only==='blocked'&&c.blocked||only==='age'&&!c.ageVerified)).map(c=>({...c,total:orders.filter(o=>o.customer===c.id&&o.status==='completed').reduce((a,o)=>a+o.total,0),count:orders.filter(o=>o.customer===c.id).length})).sort((a,b)=>b.total-a.total);
 function verify(c){form('Verificação +18 · '+c.name,<><div className="alert">CPF não comprova idade. A prévia exige data de nascimento elegível e revisão registrada. Validação documental real será uma integração separada.</div><Field label="Nascimento declarado" name="birth" type="date" value={c.birth} max={today()} required/><Field label="CPF fictício (opcional)" name="cpf" value={c.cpf} maxLength={14}/><Field label="Resultado da revisão" name="verified" options={[["no","Não verificado"],["yes","Revisado: maior de 18"]]} value={c.ageVerified?'yes':'no'}/><Field label="Observação da revisão" name="note" type="textarea" required/></>,v=>{if(v.verified==='yes'&&(ageAt(v.birth)??0)<18)throw Error('Nascimento informado não atende +18. Não é possível aprovar.');commit(x=>Object.assign(x.customers.find(a=>a.id===c.id),{birth:v.birth,cpf:v.cpf,ageVerified:v.verified==='yes'}),'Revisão de maioridade demonstrativa: '+c.name+' · '+v.note)})}
 return <><div className="section-toolbar"><div className="searchbox"><Search size={16}/><input placeholder="Buscar cliente" value={q} onChange={e=>setQ(e.target.value)}/></div><select className="small-select" aria-label="Filtrar clientes" value={only} onChange={e=>setOnly(e.target.value)}><option value="">Todos</option><option value="blocked">Bloqueados</option><option value="age">+18 pendente</option></select><Export p={p} rows={rows.map(c=>({Cliente:c.name,Cidade:c.city,Pedidos:c.count,Gasto:c.total/100,IdadeRevisada:c.ageVerified?'Sim':'Não'}))} name="nowup-clientes"/></div><Matches>Cadastro atual; total de pedidos e gasto usam o período, horário e loja filtrados. Ranking do maior gasto para o menor.</Matches><Panel title="Clientes finais e ranking de consumo" subtitle="Dados pessoais fictícios. Documentos reais não são carregados."><GridTable rows={rows} columns={[["Cliente",c=><><strong>{c.name}</strong><small>{c.phone||'Telefone não cadastrado'}</small></>],['Endereço',c=><><span>{c.address}</span><small>{c.city}</small></>],['+18',c=><Badge tone={c.ageVerified?'green':'amber'}>{c.ageVerified?'Revisado':'Pendente'}</Badge>],['Pedidos','count'],['Gasto no período',c=>money(c.total)],['Ações',c=><div className="row-actions nowrap"><Button variant="secondary small" onClick={()=>verify(c)}>Verificação</Button><Button variant="secondary small" onClick={()=>form('Editar cliente · '+c.name,<><Field label="Nome" name="name" value={c.name} required/><Field label="Telefone" name="phone" value={c.phone}/><Field label="Endereço" name="address" value={c.address}/></>,v=>commit(x=>Object.assign(x.customers.find(a=>a.id===c.id),v),'Cadastro de cliente editado'))}>Editar</Button><Button variant="secondary small" onClick={()=>confirm(c.blocked?'Desbloquear cliente?':'Bloquear cliente?',c.name,()=>commit(x=>{const t=x.customers.find(a=>a.id===c.id);t.blocked=!t.blocked},'Bloqueio de cliente alterado: '+c.name))}>{c.blocked?'Desbloquear':'Bloquear'}</Button></div>]]}/></Panel></>}
export function Products(p){const {data:d,filters:f,commit,form,ui:{Panel,Button,Badge,Field}}=p;const [filter,setFilter]=useState(''),[q,setQ]=useState('');const rows=filterRows(d.products.map(x=>({...x,neighborhood:d.stores.find(s=>s.id===x.store)?.neighborhood})),{...f,q:''}).filter(x=>(!q||x.name.toLowerCase().includes(q.toLowerCase()))&&(!filter||filter==='photo'&&!x.photo||filter==='price'&&!x.price||x.status===filter));return <><div className="section-toolbar"><div className="searchbox"><Search size={16}/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Buscar produto"/></div><select className="small-select" value={filter} aria-label="Moderação de produtos" onChange={e=>setFilter(e.target.value)}><option value="">Todos os produtos</option>{[['photo','Sem foto'],['price','Sem preço'],['Pausado','Pausado'],['Pendente','Pendente'],['Reprovado','Reprovado']].map(([v,n])=><option key={v} value={v}>{n}</option>)}</select></div><Panel title="Moderação de produtos" subtitle="Filtros de data e hora consideram o cadastro demonstrativo."><GridTable rows={rows} columns={[["Produto",x=><><strong>{x.name}</strong><small>{d.stores.find(s=>s.id===x.store)?.name}</small></>],['Categoria','category'],['Foto',x=><Badge tone={x.photo?'green':'amber'}>{x.photo?'Informada':'Ausente'}</Badge>],['Preço',x=>x.price?money(x.price):'Não informado'],['Situação',x=><Badge>{x.status}</Badge>],['Ações',x=><div className="row-actions nowrap"><Button variant="secondary small" onClick={()=>{if(!x.price){p.setToast('Informe um preço antes de aprovar.');return}commit(z=>z.products.find(a=>a.id===x.id).status='Aprovado','Produto aprovado: '+x.name)}}>Aprovar</Button><Button variant="secondary small" onClick={()=>form('Reprovar produto',<Field label="Motivo" name="reason" type="textarea" required/>,v=>commit(z=>Object.assign(z.products.find(a=>a.id===x.id),{status:'Reprovado',reason:v.reason}),'Produto reprovado: '+x.name+' · '+v.reason))}>Reprovar</Button><button className="icon-btn" aria-label={'Editar '+x.name} onClick={()=>form('Editar produto',<><Field label="Nome" name="name" value={x.name} required/><Field label="Preço (R$)" name="price" type="number" min="0" step="0.01" value={x.price/100} required/><Field label="Categoria global" name="category" options={d.productCategories} value={x.category}/><Field label="Situação" name="status" options={['Pendente','Aprovado','Pausado','Reprovado']} value={x.status}/><label className="checkbox-inline"><input type="checkbox" name="photo" defaultChecked={x.photo}/>Simular foto cadastrada</label></>,v=>{if(v.status==='Aprovado'&&Number(v.price)<=0)throw Error('Produto aprovado precisa de preço.');commit(z=>Object.assign(z.products.find(a=>a.id===x.id),{...v,price:Math.round(Number(v.price)*100),photo:v.photo==='on'}),'Produto editado: '+x.name)})}><Settings2 size={15}/></button></div>]]}/></Panel><Panel title="Categorias globais de produto" subtitle="Separadas das categorias de lojas." action={<Button icon={Plus} onClick={()=>form('Nova categoria global',<Field label="Nome" name="name" required/>,v=>{if(d.productCategories.some(c=>c.toLowerCase()===v.name.trim().toLowerCase()))throw Error('Categoria já existe.');commit(z=>z.productCategories.push(v.name.trim()),'Categoria global criada')})}>Criar categoria</Button>}><div className="global-tags">{d.productCategories.map(c=><span key={c}>{c}</span>)}</div></Panel></>}
export function Logistics(p){const {data:d,filters:f,commit,form,ui:{Panel,Button,Badge,Field}}=p;const [tab,setTab]=useState('couriers');function courier(c){form(c?'Editar motoboy':'Cadastrar motoboy',<><Field label="Nome" name="name" value={c?.name} required/><Field label="Telefone" name="phone" value={c?.phone}/><Field label="Veículo" name="vehicle" options={['Moto','Bicicleta','Carro']} value={c?.vehicle}/><Field label="Placa demonstrativa" name="plate" value={c?.plate}/><Field label="Bairro" name="neighborhood" value={c?.neighborhood}/></>,v=>commit(x=>{if(c)Object.assign(x.couriers.find(a=>a.id===c.id),v);else x.couriers.push({...v,id:newId(),enabled:true})},'Cadastro de entrega salvo'))}function rule(r){form(r?'Editar taxa regional':'Nova região de entrega',<><Field label="Cidade" name="city" options={d.settings.cities} value={r?.city||'Ubatuba'}/><Field label="Bairro" name="neighborhood" value={r?.neighborhood} required/><Field label="Taxa fixa (R$)" name="fixed" type="number" min="0" step="0.01" value={(r?.fixed||0)/100} required/><Field label="Adicional por km (R$)" name="perKm" type="number" min="0" step="0.01" value={(r?.perKm||200)/100} required/><Field label="Estimativa (minutos)" name="eta" type="number" min="1" max="240" value={r?.eta||30} required/></>,v=>commit(x=>{const a={...v,fixed:Math.round(Number(v.fixed)*100),perKm:Math.round(Number(v.perKm)*100),eta:Number(v.eta)};if(r)Object.assign(x.deliveryRules.find(a=>a.id===r.id),a);else x.deliveryRules.push({...a,id:newId()})},'Taxa de entrega regional salva'))}
return <><div className="section-tabs">{[['couriers','Motoboys'],['fees','Taxas e regiões']].map(([k,n])=><button key={k} className={tab===k?'selected':''} onClick={()=>setTab(k)}>{n}</button>)}</div><Matches>Cadastro atual. Taxas são referências demonstrativas e não alteram o checkout real.</Matches>{tab==='couriers'?<Panel title="Equipe de entrega" subtitle="O NowUp não realiza despacho real nesta prévia." action={<Button icon={Plus} onClick={()=>courier(null)}>Cadastrar motoboy</Button>}><GridTable rows={d.couriers.filter(c=>!f.neighborhood||c.neighborhood===f.neighborhood)} columns={[["Nome","name"],['Telefone',c=>c.phone||'Não informado'],['Veículo','vehicle'],['Bairro','neighborhood'],['Disponibilidade',c=><Badge>{c.enabled?'Ativo':'Inativo'}</Badge>],['Ações',c=><div className="row-actions"><Button variant="secondary small" onClick={()=>courier(c)}>Editar</Button><Button variant="secondary small" onClick={()=>commit(x=>{const t=x.couriers.find(a=>a.id===c.id);t.enabled=!t.enabled},'Disponibilidade do motoboy alterada')}>{c.enabled?'Pausar':'Ativar'}</Button></div>]]}/></Panel>:<Panel title="Taxas por km e bairro" subtitle="Fórmula de referência: taxa fixa + distância × valor por km." action={<Button icon={Plus} onClick={()=>rule(null)}>Nova região</Button>}><GridTable rows={d.deliveryRules.filter(r=>(!f.city||r.city===f.city)&&(!f.neighborhood||r.neighborhood===f.neighborhood))} columns={[["Cidade","city"],['Bairro','neighborhood'],['Fixa',r=>money(r.fixed)],['Por km',r=>money(r.perKm)],['Estimativa',r=>r.eta+' min'],['Ações',r=><Button variant="secondary small" onClick={()=>rule(r)}>Editar</Button>]]}/></Panel>}</>}
export function Support(p){const {data:d,filters:f,form,commit,setModal,ui:{Panel,Button,Badge,Field}}=p;const [status,setStatus]=useState('');const rows=filterRows(d.tickets.map(t=>({...t,neighborhood:d.stores.find(s=>s.id===t.store)?.neighborhood})),f).filter(t=>!status||t.status===status);function open(t){form('Chamado #'+t.id+' · '+t.reason,<><div className="chat-messages">{t.messages.map((m,i)=><div key={i}><strong>{m.actor}</strong><small>{new Date(m.date).toLocaleString('pt-BR')}</small><p>{m.body}</p></div>)}{!t.messages.length&&<p>Sem mensagens anteriores.</p>}</div><Field label="Resposta administrativa" name="message" type="textarea" required maxLength={1000}/><Field label="Situação" name="status" options={['Aberto','Em atendimento','Resolvido']} value={t.status}/></>,v=>commit(x=>{const a=x.tickets.find(s=>s.id===t.id);a.status=v.status;a.messages.push({actor:'Super ADM · demonstração',body:v.message,date:new Date().toISOString()})},'Resposta ao chamado #'+t.id+' registrada'))}
function intervene(t){form('Intervir na loja · chamado #'+t.id,<><Field label="Ação" name="action" options={['Advertir','Pausar pedidos','Banir / bloquear']}/><Field label="Motivo obrigatório" name="reason" type="textarea" required/><p className="muted">A intervenção afeta apenas a loja simulada e fica registrada.</p></>,v=>commit(x=>{const s=x.stores.find(a=>a.id===t.store);if(v.action==='Pausar pedidos')s.paused=true;if(v.action==='Banir / bloquear')s.blocked=true;x.tickets.find(a=>a.id===t.id).messages.push({actor:'Super ADM',body:v.action+': '+v.reason,date:new Date().toISOString()})},'Intervenção: '+v.action+' · loja #'+t.store+' · '+v.reason))}
return <><div className="section-toolbar"><select className="small-select" aria-label="Situação dos chamados" value={status} onChange={e=>setStatus(e.target.value)}><option value="">Todos os chamados</option>{['Aberto','Em atendimento','Resolvido'].map(s=><option key={s}>{s}</option>)}</select><Button icon={Plus} onClick={()=>form('Abrir chamado demonstrativo',<><Field label="Loja" name="store" options={d.stores.filter(s=>!s.demo).map(s=>[s.id,s.name])}/><Field label="Motivo" name="reason" options={['Atraso','Produto errado','Bebida quente','Denúncia','Outro']}/><Field label="Mensagem" name="message" type="textarea" required/></>,v=>commit(x=>{const s=x.stores.find(a=>a.id===Number(v.store));x.tickets.unshift({id:newId(),store:s.id,customer:null,reason:v.reason,status:'Aberto',date:today(),hour:19,city:s.city,messages:[{actor:'Super ADM',body:v.message,date:new Date().toISOString()}]})},'Chamado demonstrativo criado'))}>Novo chamado</Button></div><Panel title="Suporte, chat e denúncias" subtitle="Mensagens locais; nenhum cliente ou lojista é contatado."><GridTable rows={rows} columns={[["Chamado",t=>'#'+t.id],['Loja',t=>d.stores.find(s=>s.id===t.store)?.name],['Motivo','reason'],['Situação',t=><Badge>{t.status}</Badge>],['Data / hora',t=>t.date+' · '+t.hour+'h'],['Ações',t=><div className="row-actions"><Button variant="secondary small" onClick={()=>open(t)}>Chat / responder</Button><Button variant="secondary small" onClick={()=>intervene(t)}>Intervir</Button></div>]]}/></Panel></>}
export function TeamOps(p){const {data:d,filters:f,commit,form,confirm,setActing,ui:{Panel,Button,Badge,Field,FileField},clock}=p;const [tab,setTab]=useState('team'),[employee,setEmployee]=useState(''),[action,setAction]=useState('');function edit(s){form(s?'Editar funcionário':'Cadastrar funcionário',<><FileField label="Foto fictícia" name="photo" initial={s?.photo}/><div className="form-grid"><Field label="Nome" name="name" value={s?.name} required/><Field label="E-mail" name="email" type="email" value={s?.email} required/><Field label="Cargo" name="role" options={['Financeiro','Suporte','Marketing','Analista']} value={s?.role||'Analista'}/></div><p className="muted">Marque as permissões efetivas. O cargo é uma identificação; não concede módulos automaticamente.</p><div className="permission-grid">{PERMISSIONS.map(([id,label])=><label key={id}><input name={'perm_'+id} type="checkbox" defaultChecked={s?s.permissions.includes(id):ROLES.Analista.includes(id)}/>{label}</label>)}</div><div className="alert">Simulação de RBAC na interface. A integração precisará validar permissões em todas as rotas do servidor. Nenhuma conta real será criada aqui.</div></>,v=>{if(d.staff.some(x=>x.id!==s?.id&&x.email.toLowerCase()===v.email.trim().toLowerCase()))throw Error('E-mail já cadastrado.');commit(x=>{const obj={name:v.name.trim(),email:v.email.trim().toLowerCase(),role:v.role,photo:v.photo,permissions:PERMISSIONS.map(([k])=>k).filter(k=>v['perm_'+k]==='on')};if(s)Object.assign(x.staff.find(a=>a.id===s.id),obj);else x.staff.push({...obj,id:newId(),enabled:true})},'Cadastro e permissões alterados: '+v.name)},{wide:true})}
 const logs=filterRows(d.logs.map(l=>({...l,date:l.date.slice(0,10),hour:Number(new Intl.DateTimeFormat('en',{timeZone:'America/Sao_Paulo',hour:'numeric',hourCycle:'h23'}).format(new Date(l.date))),originalDate:l.date})),{...f,city:'',store:'',neighborhood:''}).filter(l=>(!employee||l.actor===d.staff.find(s=>s.id===Number(employee))?.name)&&(!action||l.action.toLowerCase().includes(action.toLowerCase())));
const sessions=d.sessions.filter(s=>(!employee||String(s.employee)===employee)&&s.start.slice(0,10)>=f.start&&s.start.slice(0,10)<=f.end).filter(s=>{const hour=Number(new Intl.DateTimeFormat('en',{timeZone:'America/Sao_Paulo',hour:'numeric',hourCycle:'h23'}).format(new Date(s.start)));return filterRows([{date:s.start.slice(0,10),hour}],{...f,city:'',store:'',neighborhood:''}).length});
return <><div className="section-toolbar"><div className="section-tabs">{[['team','Funcionários'],['sessions','Entradas e saídas'],['logs','Log de ações']].map(([id,n])=><button key={id} className={tab===id?'selected':''} onClick={()=>setTab(id)}>{n}</button>)}</div><Button icon={Plus} onClick={()=>edit(null)}>Novo funcionário</Button></div>{tab==='team'?<Panel title="Equipe e permissões RBAC" subtitle="Super ADM mantém acesso completo; funcionários veem apenas módulos liberados.">{d.staff.map(s=><div className="employee-card" key={s.id}><span className="avatar">{s.photo?<img src={s.photo} alt=""/>:s.name.slice(0,1)}</span><div className="employee-info"><h3>{s.name}</h3><p>{s.role} · {s.email}</p><div className="permission-tags">{s.permissions.map(id=><span key={id}>{PERMISSIONS.find(a=>a[0]===id)?.[1]||id}</span>)}</div></div><div className="row-actions"><Button variant="secondary small" onClick={()=>edit(s)}>Permissões</Button><Button variant="secondary small" disabled={!s.enabled} onClick={()=>{commit(x=>x.sessions.unshift({id:newId(),employee:s.id,start:new Date().toISOString(),end:'',lastActivity:new Date().toISOString(),state:'Conectado',device:'Sessão simulada'}),'Acesso simulado iniciado: '+s.name);setActing(String(s.id));p.navigate(s.permissions[0]||'profile')}}>Acesso de equipe</Button><Button variant="secondary small" onClick={()=>confirm('Alterar acesso do funcionário?',s.name,()=>commit(x=>{const t=x.staff.find(a=>a.id===s.id);t.enabled=!t.enabled;if(!t.enabled)for(const sess of x.sessions.filter(a=>a.employee===s.id&&!a.end)){sess.end=new Date().toISOString();sess.state='Revogada'}},'Acesso da equipe alterado: '+s.name))}>{s.enabled?'Desativar':'Reativar'}</Button></div></div>)}</Panel>:<><div className="section-toolbar"><select className="small-select" aria-label="Filtrar funcionário" value={employee} onChange={e=>setEmployee(e.target.value)}><option value="">Todos os funcionários</option>{d.staff.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select>{tab==='logs'&&<div className="searchbox"><Search size={14}/><input value={action} onChange={e=>setAction(e.target.value)} placeholder="Buscar ação"/></div>}<Export p={p} rows={tab==='sessions'?sessions.map(s=>({Funcionario:d.staff.find(e=>e.id===s.employee)?.name,Entrada:s.start,Saida:s.end||'',UltimaAtividade:s.lastActivity,Estado:sessionState(s,clock)})):logs.map(l=>({Responsavel:l.actor,DataHora:l.originalDate,Acao:l.action}))} name={'nowup-equipe-'+tab}/></div>{tab==='sessions'?<Panel title="Entradas, saídas e última atividade" subtitle="Conexão e atividade não equivalem a jornada trabalhada."><GridTable rows={sessions} columns={[["Funcionário",s=>d.staff.find(a=>a.id===s.employee)?.name],['Entrada',s=>new Date(s.start).toLocaleString('pt-BR')],['Saída',s=>s.end?new Date(s.end).toLocaleString('pt-BR'):'Sessão aberta'],['Última atividade',s=>new Date(s.lastActivity).toLocaleString('pt-BR')],['Estado',s=><Badge>{sessionState(s,clock)}</Badge>],['Ação',s=>!s.end&&<Button variant="secondary small" onClick={()=>confirm('Encerrar sessão?', 'Revogar esta sessão demonstrativa?',()=>commit(x=>Object.assign(x.sessions.find(a=>a.id===s.id),{end:new Date().toISOString(),state:'Revogada'}),'Sessão da equipe revogada'))}>Revogar</Button>]]}/><Matches>Fechar a aba não registra logout. Após 5 minutos sem atividade registrada, a simulação mostra “Sem atividade”.</Matches></Panel>:<Panel title="Quem fez o quê e quando" subtitle="Auditoria local filtrada por data, hora, funcionário e texto."><GridTable rows={logs} columns={[["Data e hora",l=>new Date(l.originalDate).toLocaleString('pt-BR')],['Responsável','actor'],['Ação','action']]}/></Panel>}</>}</>}
export function System(p){const {data:d,commit,form,filters:f,ui:{Panel,Button,Badge,Field}}=p;const [tab,setTab]=useState('integrations');function backup(){const blob=new Blob([JSON.stringify({...d,exportedAt:new Date().toISOString(),environment:'DEMONSTRATION'},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='nowup-demo-backup-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);p.setToast('Backup da demonstração exportado. Não contém o banco de produção.')}return <><div className="section-tabs">{[['integrations','Integrações'],['backup','Backup'],['errors','Log de erros']].map(([id,n])=><button key={id} className={tab===id?'selected':''} onClick={()=>setTab(id)}>{n}</button>)}</div>{tab==='integrations'&&<Panel title="Conexões e verificação" subtitle="Nenhuma chave ou credencial real é solicitada nesta prévia.">{[['Pagamentos SaaS','Asaas / Gerencianet: Pix e cartão. Webhooks e idempotência necessários.'],['WhatsApp API','Mensagens oficiais com modelos, consentimento e credenciais de servidor.'],['Push segmentado','Permissão do dispositivo e serviço de entrega necessários.'],['Verificação +18','CPF isolado não verifica idade. Revisão e confirmação na entrega precisam de integração.']].map(([a,b])=><div className="integration-row" key={a}><span className="integration-icon"><ShieldCheck size={20}/></span><div><h3>{a}</h3><p>{b}</p></div><Badge tone="amber">Não conectado</Badge></div>)}</Panel>}{tab==='backup'&&<Panel title="Backup da prévia" subtitle="Exportação e restauração local, sem tocar no banco do NowUp."><div className="settings-form"><Button icon={Download} onClick={backup}>Exportar backup JSON</Button><label className="field"><span>Restaurar backup demonstrativo</span><input type="file" accept=".json" onChange={e=>{const file=e.target.files[0];if(!file)return;if(file.size>6*1024*1024){p.setToast('Arquivo muito grande. Máximo 6 MB.');return}const reader=new FileReader();reader.onload=()=>{try{const parsed=JSON.parse(reader.result);if(parsed.operationsVersion!==2||parsed.environment!=='DEMONSTRATION'||!Array.isArray(parsed.stores)||!Array.isArray(parsed.logs)||!Array.isArray(parsed.orders)||!Array.isArray(parsed.staff)||!Array.isArray(parsed.sessions))throw Error('Backup incompatível.');p.confirm('Restaurar demonstração?','Os dados locais desta prévia serão substituídos. O site real permanece preservado.',()=>commit(x=>{for(const k of Object.keys(x))delete x[k];Object.assign(x,parsed)},'Backup demonstrativo restaurado'))}catch{p.setToast('Backup inválido ou incompatível. Nenhuma alteração realizada.')}};reader.readAsText(file);e.target.value=''}}/></label><p className="muted">Backup de produção, rotina R2 e recuperação real continuam no sistema atual e não são operados por esta tela.</p></div></Panel>}{tab==='errors'&&<Panel title="Eventos e erros locais" subtitle="Não corresponde aos logs do Render."><GridTable rows={d.errors.filter(e=>e.date.slice(0,10)>=f.start&&e.date.slice(0,10)<=f.end)} columns={[["Horário",e=>new Date(e.date).toLocaleString('pt-BR')],['Nível','level'],['Evento','message']]}/></Panel>}</>}
export function ExtraMarketing(p){const {data:d,filters:f,ui:{Panel,Button,Field},form,commit}=p;const stale=d.customers.filter(c=>(!c.lastPurchase229||c.lastPurchase229<shift(today(),-14))&&(!f.city||c.city===f.city));return <div className="two-columns"><Panel title="Reativação · 15 dias sem comprar" subtitle={`${stale.length} cliente(s) na cidade filtrada · nenhuma mensagem enviada.`}><GridTable rows={stale} columns={[["Cliente","name"],['Bairro','neighborhood']]}/><div className="settings-form"><Button onClick={()=>form('Preparar campanha de reativação',<Field label="Mensagem" name="message" type="textarea" required/>,v=>commit(x=>x.campaigns.unshift({id:newId(),title:'Reativação 15 dias',message:v.message,audience:'Clientes inativos',city:f.city||'Todas',date:new Date().toISOString(),status:'Simulada'}),'Campanha de reativação preparada, não enviada'))}>Preparar campanha</Button></div></Panel><Panel title="Indique e ganhe" subtitle="Regras de demonstração; nenhum crédito financeiro é gerado."><div className="settings-form"><p>Defina o benefício e registre indicações de teste.</p><Button variant="secondary" onClick={()=>form('Indicação demonstrativa',<><Field label="Quem indicou" name="referrer" options={d.customers.map(c=>[c.id,c.name])}/><Field label="Quem foi indicado" name="referred" options={d.customers.map(c=>[c.id,c.name])}/><Field label="Benefício (R$)" name="reward" type="number" min="0" step="0.01" value="10" required/></>,v=>{if(v.referrer===v.referred)throw Error('Não é possível indicar a si mesmo.');if(d.referrals.some(r=>r.referred===v.referred))throw Error('Cliente já tem indicação registrada.');commit(x=>x.referrals.push({...v,id:newId(),status:'Aguardando validação'}),'Indicação demonstrativa cadastrada')})}>Registrar indicação</Button><GridTable rows={d.referrals} columns={[["Indicador",r=>d.customers.find(c=>String(c.id)===r.referrer)?.name],['Indicado',r=>d.customers.find(c=>String(c.id)===r.referred)?.name],['Benefício',r=>money(Number(r.reward)*100)],['Estado','status']]}/></div></Panel></div>}
export function GlobalSettings(p){const {data:d,commit,ui:{Panel,Button,Field}}=p;return <Panel title="Operação global e texto da home" subtitle="Configurações locais da demonstração; publicação no marketplace depende da integração."><form className="settings-form" onSubmit={e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.currentTarget));commit(x=>Object.assign(x.settings,{platformHours:v.hours,globalMessage:v.message,homeTitle:v.homeTitle,homeText:v.homeText,minOrder:Math.round(Number(v.minOrder)*100),deliveryPerKm:Math.round(Number(v.fee)*100),activeCities:x.settings.cities.filter(c=>v['city_'+c]==='on')}),'Configurações globais e CMS editados')}}><div className="permission-grid">{d.settings.cities.map(c=><label key={c}><input name={'city_'+c} type="checkbox" defaultChecked={d.settings.activeCities.includes(c)}/>{c}</label>)}</div><div className="form-grid"><Field label="Horário da plataforma" name="hours" value={d.settings.platformHours} required/><Field label="Pedido mínimo (R$)" name="minOrder" type="number" min="0" step="0.01" value={d.settings.minOrder/100} required/><Field label="Taxa referência por km (R$)" name="fee" type="number" min="0" step="0.01" value={d.settings.deliveryPerKm/100} required/></div><Field label="Mensagem global" name="message" type="textarea" value={d.settings.globalMessage}/><Field label="Título da home" name="homeTitle" value={d.settings.homeTitle} required/><Field label="Texto da home" name="homeText" type="textarea" value={d.settings.homeText}/><Button type="submit" icon={Check}>Salvar na demonstração</Button></form></Panel>}
